-- =====================================================================
-- ultbigboy  --  PostgreSQL schema + data
-- Converted from phpMyAdmin / MariaDB 10.4 dump (Nov 06, 2026)
--
-- Usage:
--   createdb ultbigboy
--   psql -d ultbigboy -f ultbigboy_postgres.sql
--
-- Conversion notes:
--   * int(11)/bigint(20)  -> integer/bigint ; tinyint(4) -> smallint ; tinyint(1) -> boolean
--   * AUTO_INCREMENT      -> GENERATED BY DEFAULT AS IDENTITY (START WITH = old AUTO_INCREMENT)
--   * decimal             -> numeric ; longtext JSON -> jsonb ; timestamp/datetime -> timestamptz (UTC)
--   * ON UPDATE current_timestamp() -> trigger set_updated_at()
--   * MySQL KEY / UNIQUE KEY -> CREATE INDEX / UNIQUE
--   * MySQL case-insensitive collation -> extra unique index on lower(users.email)
--   * Foreign keys are added at the end. Some are NOT VALID because the dump
--     contains rows (licenses, license_certificates) that point at users,
--     orders, beats and order_items rows that were not exported.
-- =====================================================================

SET client_encoding = 'UTF8';
SET TIME ZONE 'UTC';

BEGIN;

-- ---------------------------------------------------------------------
-- Helper: emulate MySQL "ON UPDATE current_timestamp()"
-- ---------------------------------------------------------------------
CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- ---------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------

CREATE TABLE users (
  id                integer GENERATED BY DEFAULT AS IDENTITY (START WITH 26) PRIMARY KEY,
  name              varchar(255) NOT NULL,
  email             varchar(255) NOT NULL UNIQUE,
  first_name        varchar(255),
  last_name         varchar(255),
  artist_name       varchar(255),
  phone             varchar(255) UNIQUE,
  role              varchar(50)  NOT NULL DEFAULT 'non_artist',
  address           text,
  password_hash     varchar(255) NOT NULL,
  created_at        timestamptz  NOT NULL DEFAULT now(),
  email_verified_at timestamptz
);
-- MySQL's utf8mb4_general_ci made emails case-insensitive; keep that guarantee:
CREATE UNIQUE INDEX uq_users_email_lower ON users (lower(email));

CREATE TABLE account_tokens (
  id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id    integer     NOT NULL,
  token_hash char(64)    NOT NULL UNIQUE,
  token_type varchar(50) NOT NULL,
  expires_at timestamptz NOT NULL,
  used_at    timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_account_tokens_user_type ON account_tokens (user_id, token_type);

CREATE TABLE audit_logs (
  id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id      integer,
  action       varchar(100) NOT NULL,
  entity_type  varchar(100),
  entity_id    integer,
  details_json jsonb,
  ip_address   varchar(45),
  created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_audit_logs_user_id ON audit_logs (user_id);
CREATE INDEX idx_audit_logs_action  ON audit_logs (action);

CREATE TABLE beats (
  id                       integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title                    varchar(255) NOT NULL,
  bpm                      integer,
  musical_key              varchar(255),
  genre                    varchar(255),
  mood                     varchar(255),
  cover_art                varchar(255),
  preview_file             varchar(255),
  mp3_file                 varchar(255),
  wav_file                 varchar(255),
  stems_file               varchar(255),
  basic_price              numeric(12,2),
  premium_price            numeric(12,2),
  unlimited_price          numeric(12,2),
  exclusive_price          numeric(12,2),
  created_at               timestamptz NOT NULL DEFAULT now(),
  preview_duration_seconds integer,
  catalog_status           varchar(20) NOT NULL DEFAULT 'published'
);
CREATE INDEX idx_beats_catalog_status ON beats (catalog_status);

CREATE TABLE bookings (
  id                 integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name               varchar(255) NOT NULL,
  email              varchar(255) NOT NULL,
  phone              varchar(255),
  service            varchar(255) NOT NULL,
  artist_count       integer NOT NULL DEFAULT 1,
  song_count         integer,
  booking_slots_json jsonb,
  preferred_date     varchar(255),
  preferred_time     varchar(255),
  details            text,
  payment_reference  varchar(255) UNIQUE,
  status             varchar(50)  NOT NULL DEFAULT 'new',
  created_at         timestamptz  NOT NULL DEFAULT now(),
  admin_notes        text
);

CREATE TABLE booking_availability (
  id         integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  slot_date  date NOT NULL,
  start_time time NOT NULL,
  end_time   time NOT NULL,
  status     varchar(50) NOT NULL DEFAULT 'available',
  booking_id integer,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_booking_slot UNIQUE (slot_date, start_time)
);
CREATE INDEX idx_booking_availability_date    ON booking_availability (slot_date);
CREATE INDEX fk_booking_availability_booking  ON booking_availability (booking_id);

CREATE TABLE customer_reviews (
  id             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_name  varchar(255) NOT NULL,
  customer_email varchar(255) NOT NULL,
  rating         smallint     NOT NULL,
  review_text    text         NOT NULL,
  status         varchar(50)  NOT NULL DEFAULT 'pending',
  created_at     timestamptz  NOT NULL DEFAULT now(),
  user_id        integer
);
CREATE INDEX idx_customer_reviews_user_id        ON customer_reviews (user_id);
CREATE INDEX idx_customer_reviews_status_created ON customer_reviews (status, created_at);

CREATE TABLE customization_requests (
  id                integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  request_type      varchar(50)  NOT NULL,
  customer_name     varchar(255) NOT NULL,
  customer_email    varchar(255) NOT NULL,
  product_name      varchar(255),
  details           text,
  sample_audio_file varchar(255),
  sample_link       text,
  requested_license varchar(50),
  license_price_gsh numeric(12,2),
  status            varchar(50)  NOT NULL DEFAULT 'new',
  created_at        timestamptz  NOT NULL DEFAULT now(),
  user_id           integer,
  quote_gsh         numeric(12,2),
  admin_notes       text
);
CREATE INDEX idx_customization_requests_user_id ON customization_requests (user_id);

CREATE TABLE orders (
  id                 integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  reference          varchar(255) NOT NULL UNIQUE,
  customer_name      varchar(255) NOT NULL,
  customer_email     varchar(255) NOT NULL,
  amount             numeric(12,2) NOT NULL,
  currency           varchar(10)   NOT NULL,
  items_json         jsonb         NOT NULL,
  status             varchar(50)   NOT NULL DEFAULT 'pending',
  created_at         timestamptz   NOT NULL DEFAULT now(),
  fulfillment_status varchar(50)   NOT NULL DEFAULT 'unfulfilled',
  refunded_amount    numeric(12,2) NOT NULL DEFAULT 0.00,
  refunded_at        timestamptz
);
CREATE INDEX idx_orders_status ON orders (status);

CREATE TABLE order_items (
  id           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_id     integer       NOT NULL,
  product_type varchar(50)   NOT NULL,
  product_id   integer       NOT NULL,
  product_name varchar(255)  NOT NULL,
  license_type varchar(50),
  unit_amount  numeric(12,2) NOT NULL,
  currency     varchar(10)   NOT NULL,
  quantity     integer       NOT NULL DEFAULT 1,
  created_at   timestamptz   NOT NULL DEFAULT now()
);
CREATE INDEX idx_order_items_order_id ON order_items (order_id);

CREATE TABLE order_fulfillment_history (
  id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_id   integer     NOT NULL,
  status     varchar(50) NOT NULL,
  changed_by integer,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_order_fulfillment_history_order_created ON order_fulfillment_history (order_id, created_at);
CREATE INDEX fk_order_fulfillment_history_user           ON order_fulfillment_history (changed_by);

CREATE TABLE download_events (
  id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id      integer,
  order_id     integer     NOT NULL,
  beat_id      integer     NOT NULL,
  license_type varchar(50) NOT NULL,
  format       varchar(20) NOT NULL,
  created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_download_events_user_id  ON download_events (user_id);
CREATE INDEX idx_download_events_order_id ON download_events (order_id);

CREATE TABLE email_outbox (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  idempotency_key varchar(255) NOT NULL UNIQUE,
  recipient       varchar(320) NOT NULL,
  template        varchar(50)  NOT NULL,
  data_json       jsonb,
  status          varchar(20)  NOT NULL DEFAULT 'pending',
  attempts        integer      NOT NULL DEFAULT 0,
  next_attempt_at timestamptz  NOT NULL DEFAULT now(),
  expires_at      timestamptz,
  locked_at       timestamptz,
  sent_at         timestamptz,
  last_error      varchar(255),
  created_at      timestamptz  NOT NULL DEFAULT now()
);
CREATE INDEX idx_email_outbox_delivery ON email_outbox (status, next_attempt_at, id);
CREATE INDEX idx_email_outbox_lease    ON email_outbox (status, locked_at);

CREATE TABLE licenses (
  id               integer GENERATED BY DEFAULT AS IDENTITY (START WITH 14) PRIMARY KEY,
  user_id          integer     NOT NULL,
  beat_id          integer     NOT NULL,
  order_id         integer     NOT NULL,
  license_type     varchar(50) NOT NULL,
  certificate_path varchar(255),
  rights_json      jsonb,
  purchased_at     timestamptz NOT NULL DEFAULT now(),
  revoked_at       timestamptz,
  revoked_reason   varchar(255),
  expires_at       timestamptz,
  CONSTRAINT uq_license_order_beat UNIQUE (order_id, beat_id, license_type)
);
CREATE INDEX idx_licenses_user_id ON licenses (user_id);
CREATE INDEX idx_licenses_beat_id ON licenses (beat_id);

CREATE TABLE license_certificates (
  id                      bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 15) PRIMARY KEY,
  certificate_id          varchar(48) NOT NULL UNIQUE,
  verification_token_hash char(64)    NOT NULL UNIQUE,
  license_id              integer     NOT NULL,
  user_id                 integer     NOT NULL,
  order_id                integer     NOT NULL,
  order_item_id           integer,
  beat_id                 integer     NOT NULL,
  license_type            varchar(50) NOT NULL,
  license_terms_snapshot  jsonb       NOT NULL,
  terms_version           varchar(40) NOT NULL,
  status                  varchar(20) NOT NULL DEFAULT 'valid',
  reissued_from_id        bigint,
  issued_at               timestamptz NOT NULL DEFAULT now(),
  revoked_at              timestamptz,
  revocation_reason       varchar(500),
  pdf_storage_path        varchar(500),
  created_at              timestamptz NOT NULL DEFAULT now(),
  updated_at              timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_license_certificates_license_id    ON license_certificates (license_id);
CREATE INDEX idx_license_certificates_user_id       ON license_certificates (user_id);
CREATE INDEX idx_license_certificates_order_id      ON license_certificates (order_id);
CREATE INDEX idx_license_certificates_beat_id       ON license_certificates (beat_id);
CREATE INDEX idx_license_certificates_status_issued ON license_certificates (status, issued_at);
CREATE INDEX fk_license_certificates_order_item     ON license_certificates (order_item_id);
CREATE INDEX fk_license_certificates_reissued_from  ON license_certificates (reissued_from_id);
CREATE TRIGGER trg_license_certificates_updated_at
  BEFORE UPDATE ON license_certificates
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE license_certificate_history (
  id            bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 11) PRIMARY KEY,
  certificate_id bigint      NOT NULL,
  action        varchar(30) NOT NULL,
  actor_user_id integer,
  reason        varchar(500),
  details_json  jsonb,
  created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_license_certificate_history_certificate ON license_certificate_history (certificate_id, created_at);
CREATE INDEX fk_license_certificate_history_actor        ON license_certificate_history (actor_user_id);

CREATE TABLE license_definition_status (
  license_type varchar(50) PRIMARY KEY,
  is_active    boolean     NOT NULL DEFAULT true,
  updated_at   timestamptz NOT NULL DEFAULT now()
);
CREATE TRIGGER trg_license_definition_status_updated_at
  BEFORE UPDATE ON license_definition_status
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE license_rights (
  license_type varchar(50) PRIMARY KEY,
  rights_json  jsonb       NOT NULL,
  updated_at   timestamptz NOT NULL DEFAULT now()
);
CREATE TRIGGER trg_license_rights_updated_at
  BEFORE UPDATE ON license_rights
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE merchandise (
  id             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title          varchar(255) NOT NULL,
  description    text,
  price          numeric(12,2),
  photo          varchar(255),
  created_at     timestamptz NOT NULL DEFAULT now(),
  stock_quantity integer,
  catalog_status varchar(20) NOT NULL DEFAULT 'published'
);
CREATE INDEX idx_merchandise_stock_quantity ON merchandise (stock_quantity);
CREATE INDEX idx_merchandise_catalog_status ON merchandise (catalog_status);

CREATE TABLE merchandise_categories (
  id         integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name       varchar(100) NOT NULL UNIQUE,
  created_at timestamptz  NOT NULL DEFAULT now()
);

CREATE TABLE merchandise_variants (
  id             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  merchandise_id integer       NOT NULL,
  name           varchar(100)  NOT NULL,
  sku            varchar(100)  UNIQUE,
  price          numeric(12,2) NOT NULL,
  stock          integer       NOT NULL DEFAULT 0,
  created_at     timestamptz   NOT NULL DEFAULT now()
);
CREATE INDEX fk_merchandise_variants_product ON merchandise_variants (merchandise_id);

CREATE TABLE notifications (
  id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id    integer      NOT NULL,
  type       varchar(100) NOT NULL,
  title      varchar(255) NOT NULL,
  message    text         NOT NULL,
  read_at    timestamptz,
  created_at timestamptz  NOT NULL DEFAULT now(),
  dedupe_key varchar(255),
  CONSTRAINT uq_notifications_dedupe_key UNIQUE (dedupe_key)
);
CREATE INDEX idx_notifications_user_read ON notifications (user_id, read_at);

CREATE TABLE payments (
  id                 integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_id           integer,
  provider           varchar(50)   NOT NULL,
  provider_reference varchar(255)  NOT NULL UNIQUE,
  status             varchar(50)   NOT NULL DEFAULT 'pending',
  amount             numeric(12,2) NOT NULL,
  currency           varchar(10)   NOT NULL,
  provider_payload   jsonb,
  verified_at        timestamptz,
  created_at         timestamptz   NOT NULL DEFAULT now(),
  updated_at         timestamptz   NOT NULL DEFAULT now()
);
CREATE INDEX idx_payments_order_id ON payments (order_id);
CREATE TRIGGER trg_payments_updated_at
  BEFORE UPDATE ON payments
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE payment_webhook_events (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  provider        varchar(50)  NOT NULL,
  event_reference varchar(255) NOT NULL,
  event_type      varchar(100) NOT NULL,
  payload         jsonb        NOT NULL,
  received_at     timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT uq_payment_webhook_event UNIQUE (provider, event_reference, event_type)
);

CREATE TABLE sales (
  id              integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  sale_type       varchar(50)   NOT NULL,
  product_id      integer,
  product_name    varchar(255)  NOT NULL,
  buyer_name      varchar(255),
  buyer_email     varchar(255),
  amount          numeric(12,2) NOT NULL,
  created_at      timestamptz   NOT NULL DEFAULT now(),
  order_reference varchar(255),
  line_index      integer       NOT NULL DEFAULT 0,
  CONSTRAINT uq_sales_order_line UNIQUE (order_reference, line_index)
);

CREATE TABLE schema_migrations (
  version    integer PRIMARY KEY,
  applied_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE settings (
  setting_key   varchar(255) PRIMARY KEY,
  setting_value text NOT NULL
);

CREATE TABLE stream_releases (
  id         integer GENERATED BY DEFAULT AS IDENTITY (START WITH 16) PRIMARY KEY,
  title      varchar(255)  NOT NULL UNIQUE,
  artist     varchar(500)  NOT NULL,
  credits_json jsonb       NOT NULL,
  cover_url  varchar(1000) NOT NULL,
  links_json jsonb         NOT NULL,
  sort_order integer       NOT NULL,
  status     varchar(20)   NOT NULL DEFAULT 'published',
  created_at timestamptz   NOT NULL DEFAULT now()
);

CREATE TABLE user_sessions (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id         integer     NOT NULL,
  token_hash      char(64)    NOT NULL UNIQUE,
  role            varchar(50) NOT NULL,
  expires_at      timestamptz NOT NULL,
  created_at      timestamptz NOT NULL DEFAULT now(),
  last_used_at    timestamptz NOT NULL DEFAULT now(),
  csrf_token_hash char(64)
);
CREATE INDEX idx_user_sessions_user_id ON user_sessions (user_id);
CREATE INDEX idx_user_sessions_expiry  ON user_sessions (expires_at);

CREATE TABLE wishlists (
  id         integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id    integer     NOT NULL,
  beat_id    integer     NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_wishlist_user_beat UNIQUE (user_id, beat_id)
);
CREATE INDEX fk_wishlists_beat ON wishlists (beat_id);

CREATE TABLE withdrawals (
  id         integer GENERATED BY DEFAULT AS IDENTITY (START WITH 3) PRIMARY KEY,
  amount     numeric(12,2) NOT NULL,
  created_at timestamptz   NOT NULL DEFAULT now()
);

