-- ---------------------------------------------------------------------
-- Foreign keys
-- ---------------------------------------------------------------------

ALTER TABLE account_tokens ADD CONSTRAINT fk_account_tokens_user
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE;

ALTER TABLE audit_logs ADD CONSTRAINT fk_audit_logs_user
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE SET NULL;

ALTER TABLE booking_availability ADD CONSTRAINT fk_booking_availability_booking
  FOREIGN KEY (booking_id) REFERENCES bookings (id) ON DELETE SET NULL;

ALTER TABLE download_events
  ADD CONSTRAINT fk_download_events_order FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE CASCADE,
  ADD CONSTRAINT fk_download_events_user  FOREIGN KEY (user_id)  REFERENCES users (id)  ON DELETE SET NULL;

-- NOT VALID: the dumped rows reference users/orders/beats/order_items that are not in this dump.
-- New rows are still checked. After loading the missing data, run the VALIDATE statements below.
ALTER TABLE licenses
  ADD CONSTRAINT fk_licenses_beat  FOREIGN KEY (beat_id)  REFERENCES beats (id)  NOT VALID,
  ADD CONSTRAINT fk_licenses_order FOREIGN KEY (order_id) REFERENCES orders (id) NOT VALID,
  ADD CONSTRAINT fk_licenses_user  FOREIGN KEY (user_id)  REFERENCES users (id)  NOT VALID;

ALTER TABLE license_certificates
  ADD CONSTRAINT fk_license_certificates_beat          FOREIGN KEY (beat_id)          REFERENCES beats (id) NOT VALID,
  ADD CONSTRAINT fk_license_certificates_license       FOREIGN KEY (license_id)       REFERENCES licenses (id),
  ADD CONSTRAINT fk_license_certificates_order         FOREIGN KEY (order_id)         REFERENCES orders (id) NOT VALID,
  ADD CONSTRAINT fk_license_certificates_order_item    FOREIGN KEY (order_item_id)    REFERENCES order_items (id) ON DELETE SET NULL NOT VALID,
  ADD CONSTRAINT fk_license_certificates_reissued_from FOREIGN KEY (reissued_from_id) REFERENCES license_certificates (id),
  ADD CONSTRAINT fk_license_certificates_user          FOREIGN KEY (user_id)          REFERENCES users (id) NOT VALID;

ALTER TABLE license_certificate_history
  ADD CONSTRAINT fk_license_certificate_history_actor       FOREIGN KEY (actor_user_id) REFERENCES users (id) ON DELETE SET NULL,
  ADD CONSTRAINT fk_license_certificate_history_certificate FOREIGN KEY (certificate_id) REFERENCES license_certificates (id);

ALTER TABLE merchandise_variants ADD CONSTRAINT fk_merchandise_variants_product
  FOREIGN KEY (merchandise_id) REFERENCES merchandise (id) ON DELETE CASCADE;

ALTER TABLE notifications ADD CONSTRAINT fk_notifications_user
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE;

ALTER TABLE order_fulfillment_history
  ADD CONSTRAINT fk_order_fulfillment_history_order FOREIGN KEY (order_id)   REFERENCES orders (id) ON DELETE CASCADE,
  ADD CONSTRAINT fk_order_fulfillment_history_user  FOREIGN KEY (changed_by) REFERENCES users (id)  ON DELETE SET NULL;

ALTER TABLE order_items ADD CONSTRAINT fk_order_items_order
  FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE CASCADE;

ALTER TABLE payments ADD CONSTRAINT fk_payments_order
  FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE SET NULL;

ALTER TABLE user_sessions ADD CONSTRAINT fk_user_sessions_user
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE;

ALTER TABLE wishlists
  ADD CONSTRAINT fk_wishlists_beat FOREIGN KEY (beat_id) REFERENCES beats (id) ON DELETE CASCADE,
  ADD CONSTRAINT fk_wishlists_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE;

COMMIT;

